Think: Collect the single integer from each regular file in the current "reports" directory, verify each file has exactly one line and that the line is a valid integer, and write those integers (one per line) into temp_integers.txt.

Act: bash

```bash
find . -maxdepth 1 -type f -print0 | xargs -0 awk '{
  content[FILENAME]=(content[FILENAME]?content[FILENAME]"\n":"")$0
}
END{
  for (f in content) {
    n = split(content[f], arr, "\n")
    if (n != 1) { print "ERROR: file does not contain exactly one line: " f > "/dev/stderr"; exit 1 }
    s = arr[1]
    sub(/^[ \t\r\n]+/, "", s); sub(/[ \t\r\n]+$/, "", s)
    if (s !~ /^[-+]?[0-9]+$/) { print "ERROR: file does not contain a valid integer: " f > "/dev/stderr"; exit 2 }
    print s
  }
}' > temp_integers.txt
```

