 arr[NR]=entry
}
END {
 if (NR==0) { print "[]"; exit }
 print "[";
 for(i=1;i<=NR;i++){
  printf("%s", arr[i]);
  if(i<NR) printf(",\n");
 }
 print "\n]";
}' > root_dir_entries.json
```

